-- Ability catalog and one ability slot per pet instance.
CREATE TABLE IF NOT EXISTS pet_has_ability (
  ability_id INT UNSIGNED NOT NULL,
  species_id SMALLINT UNSIGNED NOT NULL,
  ability_name VARCHAR(120) NOT NULL,
  ability_desc TEXT NOT NULL,
  PRIMARY KEY (ability_id),
  KEY ix_pet_has_ability_species (species_id),
  CONSTRAINT fk_pet_has_ability_species FOREIGN KEY (species_id)
    REFERENCES pet_species(species_id) ON DELETE CASCADE
) ENGINE=InnoDB;

ALTER TABLE pet_instances
  ADD COLUMN ability_id INT UNSIGNED NULL AFTER initiative,
  ADD KEY ix_pet_instances_ability (ability_id),
  ADD CONSTRAINT fk_pet_instances_ability FOREIGN KEY (ability_id)
    REFERENCES pet_has_ability(ability_id) ON DELETE SET NULL;

ON DUPLICATE KEY UPDATE
  species_id = VALUES(species_id),
  ability_name = VALUES(ability_name),
  ability_desc = VALUES(ability_desc);

-- Give existing pets the first template for their species.
UPDATE pet_instances pi
JOIN (
  SELECT species_id, MIN(ability_id) AS ability_id
    FROM pet_has_ability
   GROUP BY species_id
) defaults ON defaults.species_id = pi.species_id
   SET pi.ability_id = defaults.ability_id
 WHERE pi.ability_id IS NULL;
